def is_costas(arr):
    n=len(arr)
    seen=set()
    for i in range(n):
        for j in range(i+1,n):
            dr=arr[j]-arr[i]
            dc=j-i
            if (dr,dc) in seen:
                return False
            seen.add((dr,dc))
    return True
